const AL = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

function b58encode(buf) {
  // count leading zeros
  let nz = 0;
  while (nz < buf.length && buf[nz] === 0) nz++;
  let i = 0n;
  for (const b of buf) i = i * 256n + BigInt(b);
  let s = '';
  while (i > 0n) { const r = Number(i % 58n); i = i / 58n; s = AL[r] + s; }
  return '1'.repeat(nz) + (s === '' ? '' : s);
}

function b58decode(str) {
  // python base58 b58decode: strips? it validates. leading '1' -> zero bytes
  let i = 0n;
  for (const ch of str) {
    const idx = AL.indexOf(ch);
    if (idx < 0) throw new Error('bad char ' + ch);
    i = i * 58n + BigInt(idx);
  }
  let bytes = [];
  while (i > 0n) { bytes.unshift(Number(i % 256n)); i = i / 256n; }
  let nz = 0;
  while (nz < str.length && str[nz] === '1') nz++;
  return Buffer.from(new Array(nz).fill(0).concat(bytes));
}

// candidate CPython bytes repr per RULES 1-4
function pyrepr(buf) {
  let sq = 0, dq = 0;
  for (const b of buf) { if (b === 0x27) sq++; if (b === 0x22) dq++; }
  const q = (sq > 0 && dq === 0) ? '"' : "'";
  let out = 'b' + q;
  for (const b of buf) {
    if (b === q.charCodeAt(0)) out += '\\' + q;
    else if (b === 0x5c) out += '\\\\';
    else if (b === 0x09) out += '\\t';
    else if (b === 0x0a) out += '\\n';
    else if (b === 0x0d) out += '\\r';
    else if (b < 0x20 || b >= 0x7f) out += '\\x' + b.toString(16).padStart(2, '0');
    else out += String.fromCharCode(b);
  }
  return out + q;
}
module.exports = { b58encode, b58decode, pyrepr, AL };

